CREATE TABLE public.pipeline_baselines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_pipeline_id uuid NOT NULL UNIQUE REFERENCES public.client_pipelines(id), month date NOT NULL, values jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved')), entered_by uuid, approved_by uuid, approved_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pipeline_baselines TO authenticated; GRANT ALL ON public.pipeline_baselines TO service_role;
ALTER TABLE public.pipeline_baselines ENABLE ROW LEVEL SECURITY;
CREATE POLICY baseline_read ON public.pipeline_baselines FOR SELECT TO authenticated USING (public.is_manager(auth.uid()) OR public.manages_pipeline(client_pipeline_id) OR (status='approved' AND EXISTS(SELECT 1 FROM public.client_pipelines c WHERE c.id=client_pipeline_id AND c.client_id=public.my_client_id())));
CREATE TABLE public.kpi_source_mappings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL CHECK(source IN ('metricool','localo')), external_id text NOT NULL, external_name text NOT NULL, client_pipeline_id uuid NOT NULL REFERENCES public.client_pipelines(id), confirmed_by uuid NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), active boolean NOT NULL DEFAULT true, UNIQUE(source,external_id));
GRANT SELECT ON public.kpi_source_mappings TO authenticated; GRANT ALL ON public.kpi_source_mappings TO service_role;
ALTER TABLE public.kpi_source_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY mappings_admin ON public.kpi_source_mappings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.kpi_fetched_values (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mapping_id uuid NOT NULL REFERENCES public.kpi_source_mappings(id), client_pipeline_id uuid NOT NULL REFERENCES public.client_pipelines(id), month date NOT NULL, source text NOT NULL, fetched_values jsonb NOT NULL, raw_data jsonb NOT NULL DEFAULT '{}', fetched_at timestamptz NOT NULL DEFAULT now(), corrected_values jsonb, corrected_by uuid, corrected_at timestamptz, confirmed_by uuid, confirmed_at timestamptz, approved_by uuid, approved_at timestamptz, status text NOT NULL DEFAULT 'fetched' CHECK(status IN ('fetched','confirmed','approved')), UNIQUE(mapping_id,month));
GRANT SELECT ON public.kpi_fetched_values TO authenticated; GRANT ALL ON public.kpi_fetched_values TO service_role;
ALTER TABLE public.kpi_fetched_values ENABLE ROW LEVEL SECURITY;
CREATE POLICY fetched_read ON public.kpi_fetched_values FOR SELECT TO authenticated USING(public.is_manager(auth.uid()) OR public.manages_pipeline(client_pipeline_id));
CREATE TABLE public.kpi_sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mapping_id uuid REFERENCES public.kpi_source_mappings(id), source text NOT NULL, month date, status text NOT NULL, detail text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kpi_sync_runs TO authenticated; GRANT ALL ON public.kpi_sync_runs TO service_role;
ALTER TABLE public.kpi_sync_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY sync_admin_read ON public.kpi_sync_runs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.kpi_source_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fetched_id uuid NOT NULL REFERENCES public.kpi_fetched_values(id), actor uuid, action text NOT NULL, before_values jsonb, after_values jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kpi_source_history TO authenticated; GRANT ALL ON public.kpi_source_history TO service_role;
ALTER TABLE public.kpi_source_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY source_history_read ON public.kpi_source_history FOR SELECT TO authenticated USING(public.is_manager(auth.uid()) OR EXISTS(SELECT 1 FROM public.kpi_fetched_values f WHERE f.id=fetched_id AND public.manages_pipeline(f.client_pipeline_id)));
ALTER TABLE public.monthly_reports ADD COLUMN am_review_comment text;
CREATE FUNCTION public.save_pipeline_baseline(_cp uuid,_month date,_values jsonb,_submit boolean DEFAULT false,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow pipeline_baselines; b uuid; BEGIN
 IF auth.uid() IS NULL OR NOT(public.is_manager(auth.uid()) OR (public.has_role(auth.uid(),'pipeline_manager') AND public.manages_pipeline(_cp))) THEN RAISE EXCEPTION 'Only the pipeline head or management can enter a baseline'; END IF;
 IF _month IS NULL OR _month<>date_trunc('month',_month)::date OR jsonb_typeof(_values)<>'object' OR _values='{}'::jsonb THEN RAISE EXCEPTION 'Choose a baseline month and enter KPI values'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(_values) v WHERE jsonb_typeof(v.value) NOT IN ('number','null')) THEN RAISE EXCEPTION 'Baseline values must be numbers'; END IF;
 SELECT * INTO oldrow FROM pipeline_baselines WHERE client_pipeline_id=_cp FOR UPDATE;
 IF oldrow.status='approved' AND (NOT public.is_manager(auth.uid()) OR nullif(trim(_reason),'') IS NULL) THEN RAISE EXCEPTION 'Approved baseline changes require management and a reason'; END IF;
 INSERT INTO pipeline_baselines(client_pipeline_id,month,values,status,entered_by) VALUES(_cp,_month,_values,CASE WHEN _submit THEN 'submitted' ELSE 'draft' END,auth.uid()) ON CONFLICT(client_pipeline_id) DO UPDATE SET month=excluded.month,values=excluded.values,status=CASE WHEN oldrow.status='approved' THEN 'approved' ELSE excluded.status END,updated_at=now() RETURNING id INTO b;
 INSERT INTO admin_audit_log(actor,action,target_table,target_id,details) VALUES(auth.uid(),'baseline_change','pipeline_baselines',b::text,jsonb_build_object('before',to_jsonb(oldrow),'after',_values,'month',_month,'reason',_reason));
 END $$;
CREATE FUNCTION public.approve_pipeline_baseline(_cp uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Only Management or Admin can approve baselines'; END IF; UPDATE pipeline_baselines SET status='approved',approved_by=auth.uid(),approved_at=now(),updated_at=now() WHERE client_pipeline_id=_cp AND status='submitted'; IF NOT FOUND THEN RAISE EXCEPTION 'Submit the baseline first'; END IF; INSERT INTO admin_audit_log(actor,action,target_table,target_id,details) VALUES(auth.uid(),'baseline_approved','pipeline_baselines',_cp::text,'{}'); END $$;
CREATE FUNCTION public.q57_review_open(_month date,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT _month=(date_trunc('month',_at AT TIME ZONE 'Asia/Kolkata')-interval '1 month')::date AND extract(day FROM _at AT TIME ZONE 'Asia/Kolkata') BETWEEN 1 AND 3 $$;
CREATE FUNCTION public.confirm_kpi_mapping(_source text,_external text,_name text,_cp uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin confirmation required'; END IF; IF NOT EXISTS(SELECT 1 FROM client_pipelines c JOIN pipelines p ON p.id=c.pipeline_id WHERE c.id=_cp AND p.code=CASE _source WHEN 'metricool' THEN 'social_media' WHEN 'localo' THEN 'gbp' END) THEN RAISE EXCEPTION 'Select the matching contracted pipeline'; END IF; INSERT INTO kpi_source_mappings(source,external_id,external_name,client_pipeline_id,confirmed_by) VALUES(_source,_external,_name,_cp,auth.uid()) ON CONFLICT(source,external_id) DO UPDATE SET external_name=excluded.external_name,client_pipeline_id=excluded.client_pipeline_id,confirmed_by=auth.uid(),confirmed_at=now(),active=true RETURNING id INTO mid; INSERT INTO admin_audit_log(actor,action,target_table,target_id,details) VALUES(auth.uid(),'kpi_mapping_confirmed','kpi_source_mappings',mid::text,jsonb_build_object('source',_source,'pipeline',_cp)); RETURN mid; END $$;
CREATE FUNCTION public.review_fetched_kpis(_id uuid,_values jsonb,_confirm boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f kpi_fetched_values; BEGIN SELECT * INTO f FROM kpi_fetched_values WHERE id=_id FOR UPDATE; IF f.id IS NULL OR NOT public.manages_pipeline(f.client_pipeline_id) OR NOT public.has_role(auth.uid(),'pipeline_manager') THEN RAISE EXCEPTION 'Only the assigned pipeline head can review source data'; END IF; IF NOT q57_review_open(f.month) THEN RAISE EXCEPTION 'Review the previous month on the 1st–3rd (IST)'; END IF; IF f.status='approved' THEN RAISE EXCEPTION 'Approved source values are locked'; END IF; IF jsonb_typeof(_values)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(_values) v WHERE jsonb_typeof(v.value) NOT IN ('number','null')) THEN RAISE EXCEPTION 'Corrections must contain numeric KPI values'; END IF;
 INSERT INTO kpi_source_history(fetched_id,actor,action,before_values,after_values) VALUES(_id,auth.uid(),CASE WHEN _confirm THEN 'confirmed' ELSE 'corrected' END,coalesce(f.corrected_values,f.fetched_values),_values);
 UPDATE kpi_fetched_values SET corrected_values=_values,corrected_by=auth.uid(),corrected_at=now(),confirmed_by=CASE WHEN _confirm THEN auth.uid() END,confirmed_at=CASE WHEN _confirm THEN now() END,status=CASE WHEN _confirm THEN 'confirmed' ELSE 'fetched' END WHERE id=_id; END $$;
CREATE FUNCTION public.approve_fetched_kpis(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f kpi_fetched_values; BEGIN IF NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Only Management or Admin can approve source data'; END IF; SELECT * INTO f FROM kpi_fetched_values WHERE id=_id FOR UPDATE; IF f.id IS NULL OR f.status<>'confirmed' THEN RAISE EXCEPTION 'Pipeline head confirmation is required'; END IF; IF (now() AT TIME ZONE 'Asia/Kolkata')::date<(f.month+interval '1 month 3 days')::date THEN RAISE EXCEPTION 'Management approval opens after the 3rd (IST)'; END IF; UPDATE kpi_fetched_values SET status='approved',approved_by=auth.uid(),approved_at=now() WHERE id=_id; INSERT INTO kpi_source_history(fetched_id,actor,action,before_values,after_values) VALUES(_id,auth.uid(),'approved',f.fetched_values,coalesce(f.corrected_values,f.fetched_values)); END $$;
CREATE FUNCTION public.kpi_backentry_progress(_at date DEFAULT (now() AT TIME ZONE 'Asia/Kolkata')::date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Management access required'; END IF;
 WITH cp AS (SELECT cp.id,cp.client_id,c.hotel_name,p.name pipeline_name,p.code,cp.start_date onboarding_date FROM client_pipelines cp JOIN clients c ON c.id=cp.client_id JOIN pipelines p ON p.id=cp.pipeline_id WHERE cp.status='active' AND NOT c.is_demo), coverage AS (SELECT cp.*, CASE WHEN onboarding_date IS NULL THEN NULL ELSE greatest(0,(extract(year FROM _at)::int-extract(year FROM onboarding_date)::int)*12+extract(month FROM _at)::int-extract(month FROM onboarding_date)::int) END required FROM cp), counts AS (SELECT coverage.*, (SELECT count(DISTINCT x.month) FROM (SELECT r.month FROM monthly_reports r WHERE r.client_pipeline_id=coverage.id AND EXISTS(SELECT 1 FROM kpi_entries e WHERE e.report_id=r.id AND (e.actual IS NOT NULL OR nullif(e.text_value,'') IS NOT NULL)) UNION SELECT month FROM social_kpi_entries WHERE client_pipeline_id=coverage.id UNION SELECT month FROM gbp_kpi_entries WHERE client_pipeline_id=coverage.id UNION SELECT month FROM pipeline_kpi_entries WHERE client_pipeline_id=coverage.id UNION SELECT month FROM ota_records WHERE client_pipeline_id=coverage.id) x WHERE x.month>=date_trunc('month',coverage.onboarding_date)::date AND x.month<date_trunc('month',_at)::date) entered FROM coverage)
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'client_id',client_id,'hotel',hotel_name,'pipeline',pipeline_name,'code',code,'onboarding_date',onboarding_date,'months_required',required,'months_entered',CASE WHEN required IS NULL THEN NULL ELSE entered END,'percent',CASE WHEN required IS NULL OR required=0 THEN NULL ELSE round(100.0*entered/required,1) END,'deadline','2026-11-05','date_missing',onboarding_date IS NULL) ORDER BY hotel_name,pipeline_name),'[]') INTO result FROM counts; RETURN result; END $$;
CREATE FUNCTION public.combined_monthly_report(_client uuid,_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT(public.my_client_id()=_client OR (public.is_manager(auth.uid()) AND public.can_view_client(_client))) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 SELECT jsonb_build_object('client_id',_client,'hotel_name',(SELECT hotel_name FROM clients WHERE id=_client),'month',date_trunc('month',_month)::date,'scorecard',public.hotel_scorecard(_client,_month),'sections',coalesce(jsonb_agg(jsonb_build_object('id',r.id,'pipeline_id',cp.id,'pipeline',p.name,'code',p.code,'highlights',r.highlights,'work_items',r.work_items,'next_month_action',r.next_month_action,'kpis',coalesce((SELECT jsonb_agg(jsonb_build_object('id',k.id,'name',k.name,'target',e.target,'actual',e.actual,'text_value',e.text_value,'achievement',e.achievement_pct,'baseline',CASE WHEN b.status='approved' THEN coalesce(b.values->k.id::text,b.values->k.source_key) END,'baseline_month',CASE WHEN b.status='approved' THEN b.month END) ORDER BY k.sort_order) FROM kpi_entries e JOIN kpi_definitions k ON k.id=e.kpi_definition_id LEFT JOIN pipeline_baselines b ON b.client_pipeline_id=cp.id WHERE e.report_id=r.id),'[]'),'source_values',coalesce((SELECT jsonb_agg(jsonb_build_object('source',f.source,'values',coalesce(f.corrected_values,f.fetched_values),'fetched_at',f.fetched_at)) FROM kpi_fetched_values f WHERE f.client_pipeline_id=cp.id AND f.month=r.month AND f.status='approved'),'[]')) ORDER BY p.name),'[]')) INTO result FROM monthly_reports r JOIN client_pipelines cp ON cp.id=r.client_pipeline_id JOIN pipelines p ON p.id=cp.pipeline_id WHERE r.client_id=_client AND r.month=date_trunc('month',_month)::date AND r.status='approved'; RETURN result; END $$;
CREATE FUNCTION public.my_alcor_team() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=my_client_id(); BEGIN IF c IS NULL THEN RAISE EXCEPTION 'Owner access required'; END IF; RETURN jsonb_build_object('account_manager',(SELECT pr.full_name FROM clients cl JOIN profiles pr ON pr.id=cl.account_manager_id WHERE cl.id=c),'heads',coalesce((SELECT jsonb_agg(jsonb_build_object('pipeline',p.name,'name',pr.full_name) ORDER BY p.name) FROM client_pipelines cp JOIN pipelines p ON p.id=cp.pipeline_id LEFT JOIN profiles pr ON pr.id=cp.manager_id WHERE cp.client_id=c AND cp.status='active'),'[]')); END $$;
CREATE FUNCTION public.my_documents() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=my_client_id(); BEGIN IF c IS NULL THEN RAISE EXCEPTION 'Owner access required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'type',doc_type,'file_path',file_path,'status',status) ORDER BY created_at DESC) FROM documents WHERE client_id=c AND (doc_type ILIKE '%agreement%' OR doc_type ILIKE '%invoice%') AND file_path IS NOT NULL),'[]'); END $$;
CREATE FUNCTION public.portfolio_report_health(_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Management access required'; END IF;
 WITH scores AS (SELECT c.id,c.hotel_name,(hotel_scorecard(c.id,_month)->>'overall')::numeric score,(hotel_scorecard(c.id,(_month-interval '1 month')::date)->>'overall')::numeric previous_score FROM clients c WHERE NOT c.is_demo AND EXISTS(SELECT 1 FROM monthly_reports r WHERE r.client_id=c.id AND r.month=_month AND r.status='approved')) SELECT jsonb_build_object('top',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM scores WHERE score IS NOT NULL ORDER BY score DESC,hotel_name LIMIT 3)x),'[]'),'bottom',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM scores WHERE score IS NOT NULL ORDER BY score,hotel_name LIMIT 3)x),'[]'),'at_risk',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM scores WHERE score<70 AND previous_score<70 AND EXISTS(SELECT 1 FROM monthly_reports r WHERE r.client_id=scores.id AND r.month=(_month-interval '1 month')::date AND r.status='approved'))x),'[]')) INTO result; RETURN result; END $$;
CREATE FUNCTION public.q52_approval_role_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status<>'approved') AND auth.uid() IS NOT NULL AND NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Only Management or Admin can approve reports'; END IF; IF TG_OP='UPDATE' AND NEW.am_review_comment IS DISTINCT FROM OLD.am_review_comment AND NOT(public.is_manager(auth.uid()) OR EXISTS(SELECT 1 FROM clients c WHERE c.id=NEW.client_id AND c.account_manager_id=auth.uid())) THEN RAISE EXCEPTION 'Only the Account Manager or management can review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER q52_approval_role_guard BEFORE INSERT OR UPDATE ON public.monthly_reports FOR EACH ROW EXECUTE FUNCTION public.q52_approval_role_guard();
REVOKE ALL ON FUNCTION public.save_pipeline_baseline(uuid,date,jsonb,boolean,text),public.approve_pipeline_baseline(uuid),public.confirm_kpi_mapping(text,text,text,uuid),public.review_fetched_kpis(uuid,jsonb,boolean),public.approve_fetched_kpis(uuid),public.kpi_backentry_progress(date),public.combined_monthly_report(uuid,date),public.my_alcor_team(),public.my_documents(),public.portfolio_report_health(date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_pipeline_baseline(uuid,date,jsonb,boolean,text),public.approve_pipeline_baseline(uuid),public.confirm_kpi_mapping(text,text,text,uuid),public.review_fetched_kpis(uuid,jsonb,boolean),public.approve_fetched_kpis(uuid),public.kpi_backentry_progress(date),public.combined_monthly_report(uuid,date),public.my_alcor_team(),public.my_documents(),public.portfolio_report_health(date) TO authenticated;
